package io.github.ningpp.compat;

import java.util.HashMap;
import java.util.Map;

/**
 * Replacement for System.Runtime.Serialization.SurrogateSelector (generated by
 * CSharpToJava converter).
 */
public final class SurrogateSelector {

    private final Map<Class<?>, ISerializationSurrogate> surrogates = new HashMap<>();

    public SurrogateSelector() {
    }

    public void addSurrogate(Class<?> type, __suppress__ context, ISerializationSurrogate surrogate) {
        if (type == null) {
            throw new ArgumentNullException("type");
        }
        if (surrogate == null) {
            throw new ArgumentNullException("surrogate");
        }
        surrogates.put(type, surrogate);
    }

    public void removeSurrogate(Class<?> type, __suppress__ context) {
        surrogates.remove(type);
    }

    public ISerializationSurrogate getSurrogate(Class<?> type, __suppress__ context, Object[] selectorHolder) {
        return surrogates.get(type);
    }
}
